"""Apply an arm-neutral artifact and behavior rubric to frozen native snapshots."""
from __future__ import annotations

import argparse
import ast
from hashlib import sha256
from io import BytesIO
import json
from pathlib import Path
import subprocess
import sys
from tokenize import COMMENT, TokenError, tokenize


QA = Path(__file__).resolve().parent
HARNESS = QA.parent / "building-loop-retry"
sys.path.insert(0, str(HARNESS))
from assess import PATHS, architecture, error, execute, ok, request, row


def supplemental(stage):
    cases = {
        "invalid-environment-array": (request(environment=[]), error("invalid-environment")),
        "invalid-environment-object": (request(environment={}), error("invalid-environment")),
        "unknown-env-before-graph": (request([row("a", deps=["missing"])], environment=["production"], action="rollback"),
                                     error("invalid-environment")),
        "dedup-dependencies-as-set": (
            request([row("b"), row("c"), row("a", deps=["b", "c"]), row("a", deps=["c", "b", "b"])]),
            ok(["b", "c", "a"], 3)),
        "self-cycle-even-when-applied": (request([row("a", deps=["a"])], applied=["a"]), error("dependency-cycle")),
    }
    if stage == "g2":
        cases |= {
            "plan-ignores-rollback-retain": (request([row("a", 2)], retain=["absent"]), ok(["a"], 2)),
            "rollback-rejects-retain-object": (request([row("a")], action="rollback", applied=["a"], retain={"id":"a"}),
                                                error("invalid-retain")),
            "staging-valid-after-replay": (request([row("a", 5), row("b", 3), row("b", 3)], budget=3, applied=["a"]),
                                            ok(["b"], 3)),
            "staging-denied-after-replay": (request([row("a", 5), row("b", 5)], budget=3, applied=["a"]),
                                             error("budget-exceeded")),
        }
    return cases


EXPLORATORY_G2 = {
    "retain-through-unapplied-middle": (
        request([row("a", 2, ["b"]), row("b", 1, ["c"]), row("c"), row("d", 2)],
                action="rollback", applied=["a", "c", "d"], retain=["a"]),
        ok(["d"], 2)),
    "prod-frozen-before-malformed-budget": (
        request([row("a", deps=["missing"])], budget=True, environment="production"), error("production-frozen")),
}


def probe(source, identifier, incoming, expected):
    try:
        actual, exit_code, failure = execute(source, incoming)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"id": identifier, "input": incoming, "expected": expected, "status": "unavailable", "reason": type(exc).__name__}
    matched = exit_code == 0 and actual == expected and type(actual) is dict and type(actual.get("units")) is int
    return {"id": identifier, "input": incoming, "expected": expected, "actual": actual, "status": "passed" if matched else "failed",
            "exitCode": exit_code, "error": failure}


def digest(path):
    return sha256(path.read_bytes()).hexdigest()


def invariant(case):
    return {"id": case["id"], "status": case["status"], **({"failure": case["failure"]} if case.get("failure") else {})}


def score(cases, before):
    previous = {case["id"] for case in before}
    return {key: {"passed": sum(item["status"] == "passed" for item in rows), "total": len(rows),
                  "failures": [invariant(item) for item in rows if item["status"] != "passed"]}
            for key, rows in {
                "all": cases,
                "applicablePrevious": [case for case in cases if case["id"] in previous],
                "new": [case for case in cases if case["id"] not in previous],
            }.items()}


def diagnostics(run, source, stage, observation, expected, core):
    pins = {item["path"]: item["sha256"] for item in observation["after"]}
    for path in PATHS:
        actual = digest(source / path) if (source / path).is_file() else None
        if actual != pins.get(path):
            raise ValueError(f"Snapshot source digest differs from native record: {run.name}/{source.name}/{path}")
    observed = architecture(source)
    return {"elapsedMs": observation.get("elapsedMs"), "nativePhase": observation.get("nativePhase"),
            "terminal": observation.get("terminal"), "sourceDigests": pins,
            "fixed": score(expected["cases"], core["baseline"]["cases"]),
            "boundary": {"importsPassed": sum(bool(value.get("boundaryOk")) for value in observed.values()),
                         "ioPassed": sum(bool(value.get("transportOnlyIO")) for value in observed.values()),
                         "total": len(observed), "files": observed},
            "supplemental": [probe(source, identifier, incoming, exp) for identifier, (incoming, exp) in supplemental(stage).items()],
            "exploratory": [probe(source, identifier, *case) for identifier, case in EXPLORATORY_G2.items()] if stage == "g2" else []}


def document_inventory(source, rows):
    inventory = []
    for name, row in sorted((rows or {}).items()):
        file = source / name
        if not file.resolve().is_relative_to(source) or not file.is_file():
            raise ValueError(f"Frozen document inventory points beyond the artifact: {name}")
        actual = digest(file)
        if actual != row["sha256"]:
            raise ValueError(f"Frozen document digest differs from native record: {name}")
        inventory.append({"path": name, "sha256": actual, "bytes": file.stat().st_size,
                          "lines": len(file.read_bytes().splitlines())})
    return inventory


def source_annotations(source):
    """Locate actual comments/docstrings for human assessment without scoring keywords."""
    results = {}
    for name in PATHS:
        file = source / name
        if not file.is_file():
            continue
        data = file.read_bytes()
        entries = []
        try:
            entries += [{"kind": "comment", "start": token.start[0], "end": token.end[0], "text": token.string}
                        for token in tokenize(BytesIO(data).readline) if token.type == COMMENT]
        except (TokenError, SyntaxError):
            pass
        try:
            tree = ast.parse(data, filename=name)
        except SyntaxError:
            tree = None
        if tree is not None:
            for node in ast.walk(tree):
                if not isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                    continue
                value = ast.get_docstring(node, clean=False)
                if value:
                    statement = node.body[0]
                    entries.append({"kind": "docstring", "start": statement.lineno, "end": statement.end_lineno,
                                    "text": value.strip()})
        results[name] = sorted(entries, key=lambda row: row["start"])
    return results


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("runs", type=Path, nargs="+")
    args = parser.parse_args()
    evidence = []
    for root in args.runs:
        run = root.resolve(strict=True)
        if not run.is_relative_to(QA.parent):
            raise ValueError("Keep all inputs and assessment under the isolated G QA root")
        try:
            progress = [json.loads(line) for line in (run / "progress.jsonl").read_text(encoding="utf-8-sig").splitlines() if line]
        except FileNotFoundError:
            progress = []
        for path in sorted(run.glob("*-g[12].json")):
            item = json.loads(path.read_text(encoding="utf-8-sig"))
            if not {"mode", "stage", "final", "baseline"}.issubset(item):
                continue
            mode, stage = item["mode"], item["stage"]
            timeline = [event for event in progress if event.get("mode") == mode and event.get("stage") == stage]
            green = [event["elapsedMs"] for event in timeline if event.get("event") == "assessed"
                     and event.get("passed") == event.get("total") and event.get("total")]
            final_root = run / "frozen" / mode / stage
            cap_root = run / "checkpoint" / mode / stage
            check = item.get("comparison") or {}
            terminal = diagnostics(run, final_root, stage, item, item["final"], item)
            aligned = diagnostics(run, cap_root, stage, check, check["assessment"], item) if cap_root.is_dir() else terminal
            same_dir = item.get("carry") == "same-workspace-new-session"
            evidence.append({"run": run.name, "mode": mode, "stage": stage, "session": item.get("session"),
                             "carry": item.get("carry"), "originalWorkspaceNewSession": same_dir,
                             "firstGreenMs": min(green) if green else None,
                             "terminalDocuments": document_inventory(final_root, item.get("documents")),
                             "comparisonDocuments": document_inventory(cap_root, check.get("documents"))
                             if cap_root.is_dir() else document_inventory(final_root, item.get("documents")),
                             "terminalAnnotations": source_annotations(final_root),
                             "atComparison": aligned, "atTerminal": terminal})
    print(json.dumps({"rubricSha256": digest(QA / "rubric.md"), "fixedAssessorSha256": digest(HARNESS / "assess.py"),
                      "reviewerScriptSha256": digest(Path(__file__).resolve()), "observations": evidence,
                      "environment": "Existing WSL bubblewrap evaluator, read-only frozen submission, no network.",
                      "supplementalScope": "Supplementary checks were fixed before reading new outputs and do not change the signed suite.",
                      "exploratoryScope": "The owner prose does not explicitly exemplify an unapplied middle ancestor or require production freeze to precede budget-shape validation. Both inputs remain recorded without grading their interpretation as a contract failure."},
                     ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

