/** Extract exact successful G2 reads of G1 artifacts from isolated DSH journals. */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { zstdDecompressSync } from 'node:zlib';

const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const id = value => createHash('sha256').update(value).digest('hex').slice(0, 12);
const arms = ['standard', 'standard-checklist', 'building-loop'];
const lanes = { standard: 'std', 'standard-checklist': 'check', 'building-loop': 'bl' };
const ownerInputs = new Set(['SPEC.md', 'PROJECT-GOAL.md', 'CHANGE-G2.md', 'INDEX.md']);
const read = path => JSON.parse(readFileSync(path, 'utf8'));

function journal(path) {
  const buffer = readFileSync(path);
  const starts = [];
  for (let offset = 0; (offset = buffer.indexOf(magic, offset)) >= 0; offset += magic.length) starts.push(offset);
  return starts.flatMap((offset, n) => zstdDecompressSync(buffer.subarray(offset, starts[n + 1])).toString('utf8')
    .trim().split('\n').filter(Boolean).map(JSON.parse));
}

function parseArguments(part) {
  try { return typeof part.arguments === 'string' ? JSON.parse(part.arguments) : part.arguments; }
  catch { return null; }
}

function normalize(path, laneRoot) {
  if (typeof path !== 'string') return undefined;
  const clean = path.replaceAll('\\', '/').replace(/^\.\//u, '');
  if (clean.toLowerCase().startsWith(laneRoot.toLowerCase() + '/')) return clean.slice(laneRoot.length + 1);
  return /^[^:/]+(?:\/[^:/]+)*$/u.test(clean) && !clean.split('/').includes('..') ? clean : undefined;
}

function findings(events, laneRoot, eligible, sourceNames) {
  const toolResults = new Map(events.filter(event => event.type === 'tool/result')
    .map(event => [event.data?.message?.toolCallId, event]));
  const found = [];
  for (const event of events.filter(row => row.type === 'assistant/message')) {
    for (const part of event.data?.message?.content ?? []) {
      if (part.type !== 'tool-call') continue;
      const args = parseArguments(part);
      const result = toolResults.get(part.id);
      const message = result?.data?.message;
      if (!args || !message || message.isError) continue;
      const location = normalize(args.path ?? args.file_path ?? args.filePath, laneRoot);
      if ((part.name === 'read' || part.name === 'building_loop_file' && args.action === 'read') &&
          (eligible.has(location) || sourceNames.has(location))) {
        let returned;
        try { returned = JSON.parse(message.content?.find(item => item.type === 'text')?.text); } catch {}
        found.push({ tool: part.name, requestSeq: event.seq, resultSeq: result.seq, path: location,
          origin: sourceNames.has(location) ? 'carried-source' : 'carried-project-artifact',
          observedDigest: returned?.sha256 ?? returned?.fileSha256, expectedDigest: eligible.get(location) ?? sourceNames.get(location) });
      }
      if (part.name === 'building_loop' && args.action === 'prepare') {
        // A successful prepare may return files automatically. Count only entries with actual returned line content.
        for (const item of message.content ?? []) {
          if (item.type !== 'text') continue;
          let packet;
          try { packet = JSON.parse(item.text); } catch { continue; }
          for (const file of packet.files ?? []) {
            const location = normalize(file.path, laneRoot);
            if ((eligible.has(location) || sourceNames.has(location)) && file.lines?.length) {
              found.push({ tool: 'building_loop prepare', requestSeq: event.seq, resultSeq: result.seq,
                path: location, origin: sourceNames.has(location) ? 'carried-source' : 'carried-project-artifact',
                returnedLines: file.lines.length, observedDigest: file.sha256 ?? file.fileSha256,
                expectedDigest: eligible.get(location) ?? sourceNames.get(location) });
            }
          }
        }
      }
    }
  }
  return found;
}

function collect(run) {
  const root = join(run, 'h', 'sessions');
  const sessions = new Map();
  for (const workspace of readdirSync(root, { withFileTypes: true }).filter(row => row.isDirectory())) {
    const dir = join(root, workspace.name);
    for (const entry of readdirSync(dir, { withFileTypes: true }).filter(row => row.isDirectory() && /^(?:session-)?[0-9a-f-]{36}$/u.test(row.name))) {
      const path = join(dir, entry.name, 'session.v4.jsonl.zstd');
      if (existsSync(path)) for (const value of [entry.name, entry.name.replace(/^session-/u, '')]) sessions.set(id(value), path);
    }
  }
  return arms.flatMap(mode => {
    const firstPath = join(run, mode + '-g1.json'), secondPath = join(run, mode + '-g2.json');
    if (!existsSync(firstPath) || !existsSync(secondPath)) return [];
    const first = read(firstPath), second = read(secondPath);
    const secondIds = { [mode === 'building-loop' ? 'coordinator' : 'standard']: second.session, ...second.roleIdentity };
    const authored = Object.keys(first.documents ?? {}).filter(path => !ownerInputs.has(path));
    const sameWorkspace = second.carry === 'same-workspace-new-session';
    const eligible = new Map([...authored.map(path => [path, first.documents[path].sha256]),
      ...(sameWorkspace ? (first.extraPython ?? []).map(path => [path, undefined]) : [])]);
    const sourceNames = new Map(first.after.map(row => [row.path, row.sha256]));
    const lane = join(run, 'work', lanes[mode] + (sameWorkspace ? '' : '2')).replaceAll('\\', '/');
    const roles = Object.entries(secondIds).map(([role, id]) => {
      const file = sessions.get(id);
      if (!file) return { role, session: id, status: 'journal-missing', reads: [] };
      try { return { role, session: id, status: 'observed', reads: findings(journal(file), lane, eligible, sourceNames) }; }
      catch (error) { return { role, session: id, status: error.name, reads: [] }; }
    });
    return [{ mode, previousSession: first.session, currentSession: second.session,
      originalDirectory: sameWorkspace, distinctSession: first.session !== second.session,
      exactSourceCarry: JSON.stringify(first.after) === JSON.stringify(second.before), authoredG1Documents: authored,
      extraG1PythonPaths: first.extraPython ?? [], roles }];
  });
}

const rows = [];
for (const value of process.argv.slice(2)) {
  const run = resolve(value);
  if (!/^G:\/CodexProjects\/DSH\/outputs\//iu.test(run.replaceAll('\\', '/'))) throw Error('Use the isolated G QA run root.');
  rows.push({ run: run.replaceAll('\\', '/').split('/').at(-1), observations: collect(run) });
}
console.log(JSON.stringify({ note: 'Successful tool reads are access evidence, not proof of reasoning or fresh directory for fallback.',
  content: rows }, null, 2));

