        "journal.py": [
          {
            "kind": "docstring",
            "start": 1,
            "end": 9,
            "text": "Normalize release records at the input boundary.\n\nImport direction: this module imports nothing from the other three modules; it\nis the identity/replay layer that planner.py consumes.\n\nThe specific failure code travels in the exception message because planner.py\nmaps ``str(exc)`` straight into the transport result; callers must not infer the\ncode from the exception type."
          },
          {
            "kind": "docstring",
            "start": 17,
            "end": 23,
            "text": "Return depends_on as a sorted tuple of ids, or raise JournalError.\n\n    ``depends_on`` defaults to empty. A non-list value, a non-string entry, or\n    an empty-string entry is malformed input (``invalid-change``). Repeated\n    edges collapse here so record equality compares dependency *sets*, as SPEC\n    requires, instead of list order or multiplicity."
          },
          {
            "kind": "docstring",
            "start": 37,
            "end": 40,
            "text": "Validate one change record and return its normalized form.\n\n    ``type(...) is not int`` deliberately excludes bool, which subclasses int."
          },
          {
            "kind": "docstring",
            "start": 54,
            "end": 54,
            "text": "Equality key: id, component, units and the dependency set."
          },
          {
            "kind": "docstring",
            "start": 59,
            "end": 64,
            "text": "Validate, fold identical duplicates, and reject conflicting ids.\n\n    Returns normalized records in first-seen order, one per id. Folding happens\n    here and not in planner.py so that a repeated id can neither double-count\n    units nor create a second graph node during accounting or graph building."
          },
          {
            "kind": "comment",
            "start": 76,
            "end": 76,
            "text": "# Same id, different content: the request is ambiguous, so fail"
