            "kind": "comment",
            "start": 24,
            "end": 24,
            "text": "# catch sits only around parsing so a planner bug is never reported as"
          },
          {
            "kind": "comment",
            "start": 25,
            "end": 25,
            "text": "# a transport error."
          }
