          {
            "kind": "comment",
            "start": 10,
            "end": 10,
            "text": "# fails closed here, before any actions are emitted."
          },
          {
            "kind": "docstring",
            "start": 22,
            "end": 27,
            "text": "Validate environment, action and budget; return the budget.\n\n    The budget is validated for every action, but the ceiling is applied only by\n    plan. Rollback walks a persisted journal, so capping it would leave the\n    environment half-reverted; see allows() below."
          },
          {
            "kind": "comment",
            "start": 35,
            "end": 35,
            "text": "# type() rather than isinstance() so booleans never count as a budget."
